$('#brief-open').onclick=()=>{if(!guard())return;if(!isOwner()){toast('The board owner creates shared vendor briefs.');return}selected=new Set();$('#brief-title').value='';$('#brief-instructions').value='';$('#brief-error').textContent='';$('#brief-result').hidden=true;$('#create-brief').disabled=false;briefChoices();$('#brief-modal').showModal()};$('#select-chosen').onclick=()=>{selected=new Set(filtered().filter(i=>['Chosen','Purchased / booked'].includes(i.status)).map(i=>i.id));briefChoices()};$('#clear-selection').onclick=()=>{selected.clear();briefChoices()};
