$('#create-brief').onclick=async()=>{if(demo){$('#brief-error').textContent='Sign in to create a shareable brief from your saved board. You can preview and print this example.';return}$('#brief-error').textContent='';$('#create-brief').disabled=true;try{const payload=briefPayload(),title=$('#brief-title').value.trim();if(!title)throw Error('Give your brief a title.');const d=check(await db.from('wedding_studio_briefs').insert({user_id:boardOwner||user.id,title,payload}).select('token').single());const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('brief',d.token);$('#brief-link').value=url.href;$('#open-brief').href=url.href;$('#brief-result').hidden=false;toast('Your read-only brief is ready')}catch(e){$('#brief-error').textContent=e.message;$('#create-brief').disabled=false}};
