$('#auth-form').onsubmit=async e=>{e.preventDefault();if(!db){$('#auth-error').textContent='The connection could not start. Please reload and try again.';return}$('#auth-submit').disabled=true;$('#auth-error').textContent='';const email=$('#auth-email').value.trim(),password=$('#auth-password').value;try{if(authMode==='recover'){check(await db.auth.resetPasswordForEmail(email,{redirectTo:AUTH_RETURN_URL}));$('#auth-next').hidden=false;$('#auth-resend').hidden=true;$('#auth-submit').hidden=true;$('#auth-message').textContent='If an account exists for this email, a fresh password-reset link has been requested. Open the newest email and use its link once. It should return you to Wedding Studio to choose a new password.';return}if(authMode==='reset'){check(await db.auth.updateUser({password}));$('#auth-password').value='';$('#auth').close();toast('Password updated');await loadCloud();return}const r=authMode==='signup'?await db.auth.signUp({email,password,options:{emailRedirectTo:AUTH_RETURN_URL}}):await db.auth.signInWithPassword({email,password});const data=check(r);if(!data.session){$('#auth-next').hidden=false;$('#auth-submit').hidden=true;$('#auth-message').textContent='If this is a new email address, check your inbox and spam folder for a confirmation link. Already have a Tiny Site Studios account? No new confirmation is needed—sign in with your existing password, or choose Forgot password. For privacy, this screen cannot confirm whether an address is registered.';return}user=data.user;$('#auth').close();category='All inspiration';await loadCloud()}catch(err){$('#auth-error').textContent=err.code==='invalid_credentials'?'That email and password did not match. Try again, or choose Forgot password to reset your TSS password.':err.message||'Unable to sign in. Please try again.'}finally{$('#auth-submit').disabled=false}};
