wrap.ondblclick=e=>{if(!captureAllowed(e)||e.target.closest('.card,button,a,input,select,textarea,.board-dock'))return;const rect=$('#board').getBoundingClientRect();openEditor('note',null,view==='canvas'?{x:Math.max(0,Math.min(10000,Math.round(e.clientX-rect.left))),y:Math.max(0,Math.min(10000,Math.round(e.clientY-rect.top)))}:null)};
function captureAllowed(e){return !loading&&!$('#app').hidden&&!e.target.closest?.('input,textarea,select,[contenteditable="true"]')&&!$$('dialog[open]').length}
let internalDrag=false,dragDepth=0;
document.addEventListener('dragstart',e=>{internalDrag=!!e.target.closest?.('#board')});
document.addEventListener('dragend',()=>{internalDrag=false;dragDepth=0;document.body.classList.remove('drop-active')});
document.addEventListener('dragover',e=>{if(captureAllowed(e)&&!internalDrag){e.preventDefault();e.dataTransfer.dropEffect='copy'}});
document.addEventListener('dragenter',e=>{if(captureAllowed(e)&&!internalDrag){e.preventDefault();dragDepth++;document.body.classList.add('drop-active')}});
document.addEventListener('dragleave',()=>{if(--dragDepth<=0){dragDepth=0;document.body.classList.remove('drop-active')}});
document.addEventListener('drop',e=>{dragDepth=0;document.body.classList.remove('drop-active');if(!captureAllowed(e)||internalDrag)return;e.preventDefault();const rect=$('#board').getBoundingClientRect();const capture=StudioIntake.read(e.dataTransfer);if(view==='canvas')capture.position={x:Math.max(0,Math.round(e.clientX-rect.left)),y:Math.max(0,Math.round(e.clientY-rect.top))};void receiveCapture(capture)});
document.addEventListener('paste',e=>{if(!captureAllowed(e))return;const capture=StudioIntake.read(e.clipboardData);if(capture.entries.length){e.preventDefault();void receiveCapture(capture)}});
$('#capture-help').onclick=()=>$('#capture-modal').showModal();
async function receiveCapture(capture){if(!capture.entries.length)return;if(!user&&!demo){pendingCapture=capture;showAuth();toast('Sign in to save these ideas. They’re held here while you sign in.');return}await importCapture(capture)}
function importMessage(text,failed=[]){const el=$('#import-status');el.hidden=false;el.textContent=text;if(failed.length){const retry=document.createElement('button');retry.className='quiet';retry.textContent='Retry failed items';retry.onclick=()=>importCapture({entries:failed});el.append(retry)}const close=document.createElement('button');close.className='quiet';close.textContent='Dismiss';close.onclick=()=>el.hidden=true;el.append(close)}
async function importCapture(capture){if(importing){toast('Please wait for this batch to finish, then paste or drop again.');return}if(!guard())return;importing=true;const owner=user?.id,isDemo=demo,targetCategory=category==='All inspiration'?(memberTags?.[0]||'Sort later'):category;const entries=capture.entries.slice(0,30),failed=[],newLinks=[];let added=0;busy(true);$('#search').value='';$('#status-filter').value='';
try{for(let n=0;n<entries.length;n++){if(user?.id!==owner||demo!==isDemo)break;const entry=entries[n];importMessage(`Adding ${n+1} of ${entries.length}…`);let uploaded=null;try{const pos=capture.position;const i={id:crypto.randomUUID(),title:(entry.title||'A new idea').slice(0,200),kind:entry.kind,category:targetCategory,tags:[targetCategory],status:'Idea',notes:entry.notes||'',url:entry.url||'',colors:[],preview:entry.image?{image:entry.image}:{},x:Math.min(10000,pos?pos.x+n*24:25+items.length%3*290),y:Math.min(10000,pos?pos.y+n*24:25+Math.floor(items.length/3)*460)};
if(entry.file){const f=entry.file;if(!StudioPlanning.allowedFile(f))throw Error('Use image/document uploads or save video/audio links');if(f.size>15*1024*1024)throw Error('File exceeds 15 MB');i.kind=/^image\/(jpeg|png|webp|gif|avif)$/.test(f.type)?'image':'file';i.file_name=f.name;i.file_type=f.type||'application/octet-stream';if(demo)i.file_url=URL.createObjectURL(f);else{uploaded=(boardOwner||user.id)+'/'+user.id+'/'+crypto.randomUUID()+'/'+f.name.replace(/[^a-zA-Z0-9._-]/g,'_');check(await db.storage.from('wedding-studio').upload(uploaded,f,{contentType:i.file_type,upsert:false}));i.file_path=uploaded}}
if(user?.id!==owner||demo!==isDemo)throw Error('Session changed');await persistItem(i);added++;if(i.kind==='link')newLinks.push(i.id);
}catch(e){if(uploaded&&user?.id===owner)await db.storage.from('wedding-studio').remove([uploaded]);failed.push(entry)}}
importMessage(`${added} idea${added!==1?'s':''} added${demo?' to the temporary example':''}.${failed.length?' '+failed.length+' could not save. Check the connection and 15 MB file limit.':''}${capture.entries.length>30?' Only the first 30 were added; drop the rest as another batch.':''}`,failed);
}finally{importing=false;busy(false)}
for(const id of newLinks){if(user?.id!==owner||demo!==isDemo)break;await enrichItem(id,true)}}
const previewInFlight=new Set();
async function fetchLinkPreview(url){if(demo&&url!=='https://tinysitestudios.com/weddings/demos/garden/')throw Error('Automatic previews are available on your saved board. You can upload a cover in this example.');const session=check(await db.auth.getSession()).session;if(!session&&!demo)throw Error('Sign in to refresh the preview.');const r=await fetch(URL_BASE+'/functions/v1/wedding-studio-link-preview',{method:'POST',headers:{'Content-Type':'application/json','apikey':API_KEY,...(session?{'Authorization':'Bearer '+session.access_token}:{})},body:JSON.stringify({url}),signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Preview unavailable. Add a cover image instead.');return data}
async function enrichItem(id,replaceTitle=false){const original=items.find(i=>i.id===id);if(!original?.url||demo||!user||previewInFlight.has(id))return;const owner=user.id;previewInFlight.add(id);try{let preview;try{preview=await fetchLinkPreview(original.url)}catch{preview={checked_at:new Date().toISOString()}}const latest=items.find(i=>i.id===id);if(user?.id!==owner||!latest||latest.url!==original.url)return;preview={...latest.preview,...preview,image:preview.image||latest.preview?.image||''};await persistItem({...latest,preview,title:replaceTitle&&preview.title&&latest.title===original.title?preview.title:latest.title})}catch{/* Saving the original link is independent of preview availability. */}finally{previewInFlight.delete(id)}}
async function enrichExisting(){const owner=user?.id;for(const i of items.filter(i=>i.kind==='link'&&!i.preview?.checked_at).slice(0,20)){if(user?.id!==owner||demo)break;await enrichItem(i.id,false)}}
$('#refresh-preview').onclick=async()=>{const url=safeUrl($('#item-url').value);if(!url){$('#preview-feedback').textContent='Enter a complete website link first.';return}$('#refresh-preview').disabled=true;$('#preview-feedback').textContent='Looking for a preview…';try{const found=await fetchLinkPreview(url);draftPreview={...found,image:found.image||draftPreview.image||''};if(!$('#item-title').value&&draftPreview.title)$('#item-title').value=draftPreview.title;$('#preview-feedback').textContent=draftPreview.image?'Preview found. Save this item to apply it.':'Page details found, but no cover. Upload an image below.'}catch(e){$('#preview-feedback').textContent=e.message}finally{$('#refresh-preview').disabled=false}};
