async function loadPublicBrief(token){$('#app').hidden=true;const host=document.createElement('div');host.id='public-brief';host.innerHTML='<p class="loading">Opening your vendor brief…</p>';document.body.prepend(host);try{const r=await fetch(URL_BASE+'/functions/v1/wedding-studio-brief?token='+encodeURIComponent(token));const data=await r.json();if(!r.ok)throw Error(data.error||'Unable to open brief');host.innerHTML=briefHTML(data);document.title=data.title+' | Wedding Studio'}catch(e){host.innerHTML=`<div class="empty"><h2>This brief isn’t available.</h2><p>${esc(e.message)}</p><p>Ask the couple for a fresh link.</p></div>`}}

function setPalette(colors){draftColors=colors.filter(c=>/^#[0-9a-f]{6}$/i.test(c)).slice(0,6).map(c=>c.toUpperCase());$('#item-colors').value=draftColors.join(', ');renderPalette()}
function renderPalette(){
 $('#palette-swatches').innerHTML=draftColors.map((c,n)=>`<div class="palette-swatch"><label><span class="sr-only">Color ${n+1}</span><input type="color" value="${c}" data-color="${n}"><span class="color-code">${c}</span></label><button type="button" class="quiet" data-remove-color="${n}" aria-label="Remove color ${n+1}" ${draftColors.length===1?'disabled':''}>Remove</button></div>`).join('');
 $('#palette-add').disabled=draftColors.length>=6;
 $$('[data-color]').forEach(el=>el.oninput=()=>{draftColors[Number(el.dataset.color)]=el.value.toUpperCase();el.nextElementSibling.textContent=el.value.toUpperCase();$('#item-colors').value=draftColors.join(', ')});
 $$('[data-remove-color]').forEach(el=>el.onclick=()=>setPalette(draftColors.filter((_,n)=>n!==Number(el.dataset.removeColor))));
}
$('#palette-add').onclick=()=>{if(draftColors.length<6)setPalette([...draftColors,'#E9D6CF'])};
$('#palette-apply').onclick=()=>{const colors=StudioPalette.parse($('#item-colors').value);if(!colors.length||colors.length>6||colors.some(c=>!/^#[0-9A-F]{6}$/.test(c))){$('#palette-feedback').textContent='Check the codes: use up to six colors, like #743B61, separated by commas or spaces.';return}setPalette(colors);$('#palette-feedback').textContent='Your colors are ready. Tap any swatch to adjust.'};
$('#editor').addEventListener('close',()=>{paletteJob++;$('#item-save').disabled=false});
$('#palette-photo').onchange=async()=>{
 const file=$('#palette-photo').files[0],job=++paletteJob;$('#item-save').disabled=false;if(!file)return;
 if(!/^image\/(jpeg|png|webp|gif|avif)$/.test(file.type)||file.size>15*1024*1024){$('#palette-feedback').textContent='Choose a JPG, PNG, WebP, GIF, or AVIF image under 15 MB.';return}
 $('#palette-feedback').textContent='Finding the colors in your photo…';$('#item-save').disabled=true;
 const url=URL.createObjectURL(file);
 try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('This image could not be opened. Try another photo.'));img.src=url});
 const scale=Math.min(1,160/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,canvas.width,canvas.height);const colors=StudioPalette.extract(ctx.getImageData(0,0,canvas.width,canvas.height).data);
 if(!colors.length)throw Error('No visible colors found. Try a different photo.');if(job!==paletteJob)return;
 setPalette(colors);$('#palette-feedback').textContent=`Found ${colors.length} color${colors.length===1?'':'s'}. Tap a swatch to fine-tune your palette.`;if(!$('#item-title').value)$('#item-title').value='Colors from '+file.name.replace(/\.[^.]+$/,'').slice(0,160);
 }catch(e){if(job===paletteJob)$('#palette-feedback').textContent=e.message||'Could not read this image. Try another photo.'}finally{URL.revokeObjectURL(url);if(job===paletteJob)$('#item-save').disabled=false}
};
