function renderTagPicker(){const locked=!isOwner()&&memberRole!=='partner'&&!!editing;const available=memberRole==='contribute'&&!editing?memberTags||[]:allTags();$('#item-tags').innerHTML=[...new Set([...available,...draftTags])].map(t=>`<label><input type="checkbox" data-tag value="${esc(t)}" ${draftTags.includes(t)?'checked':''} ${locked?'disabled':''}>${esc(t)}</label>`).join('');$$('[data-tag]').forEach(el=>el.onchange=()=>{draftTags=$$('[data-tag]:checked').map(el=>el.value)});$('#create-tag').disabled=locked||memberRole==='contribute';$('#new-tag').disabled=locked||memberRole==='contribute'}
$('#create-tag').onclick=()=>{const tag=$('#new-tag').value.trim().slice(0,40);if(!tag||tag==='All inspiration')return;draftTags=StudioPlanning.tags([...draftTags,tag]);board.custom_tags=StudioPlanning.tags([...(board.custom_tags||[]),tag]);$('#new-tag').value='';renderTagPicker()};
function taskCardHTML(i,readonly=false){const tasks=i.tasks||[],editable=!readonly&&canEditItem(i),row=t=>`<div class="task-row ${t.status==='done'?'task-done':''}" ${editable&&i.task_view==='kanban'?`draggable="true" data-task-drag="${esc(t.id)}" data-task-item="${esc(i.id)}"`:''}><label><input type="checkbox" ${t.status==='done'?'checked':''} ${editable?'':'disabled'} data-task-check="${esc(t.id)}" data-task-item="${esc(i.id)}"><span>${esc(t.text)}</span></label>${t.due||t.owner?`<small>${esc(t.due)}${t.owner?' · '+esc(t.owner):''}</small>`:''}${editable&&i.task_view==='kanban'?`<select aria-label="Progress for ${esc(t.text)}" data-task-status="${esc(t.id)}" data-task-item="${esc(i.id)}">${['todo','doing','done'].map((s,n)=>`<option value="${s}" ${t.status===s?'selected':''}>${['To do','In progress','Done'][n]}</option>`).join('')}</select>`:''}</div>`;
return `<div class="task-content"><div class="task-summary">${tasks.filter(t=>t.status==='done').length} / ${tasks.length} complete ${editable?`<button data-task-view="${esc(i.id)}" class="quiet">${i.task_view==='kanban'?'Checklist':'Task board'}</button>`:''}</div>${i.task_view==='kanban'?`<div class="mini-kanban">${['todo','doing','done'].map((s,n)=>`<section data-task-lane="${s}" data-task-item="${esc(i.id)}"><h4>${['To do','In progress','Done'][n]}</h4>${tasks.filter(t=>t.status===s||!t.status&&s==='todo').map(row).join('')||'<p class="hint">Drop a task here</p>'}</section>`).join('')}</div>`:`<div class="task-checklist">${tasks.map(row).join('')}</div>`}</div>`}
function renderDraftTasks(){ $('#draft-task-list').innerHTML=draftTasks.map((t,n)=>`<div class="draft-task"><input data-draft-text="${n}" value="${esc(t.text)}" aria-label="Task ${n+1}" maxlength="300" placeholder="What needs doing?"><div class="task-details"><input type="date" data-draft-due="${n}" value="${esc(t.due||'')}" aria-label="Task ${n+1} due date"><input data-draft-owner="${n}" value="${esc(t.owner||'')}" aria-label="Task ${n+1} owner" placeholder="Who’s doing it?" maxlength="100"><select data-draft-status="${n}" aria-label="Task ${n+1} progress">${['todo','doing','done'].map((s,j)=>`<option value="${s}" ${t.status===s?'selected':''}>${['To do','In progress','Done'][j]}</option>`).join('')}</select><label class="check-label"><input type="checkbox" data-draft-fixed="${n}" ${t.fixed?'checked':''}>Fixed date</label><button type="button" class="quiet" data-draft-remove="${n}" aria-label="Remove task ${n+1}">×</button></div></div>`).join('');for(const field of ['text','due','owner','status','fixed'])$$(`[data-draft-${field}]`).forEach(el=>el.oninput=()=>{draftTasks[Number(el.dataset['draft'+field[0].toUpperCase()+field.slice(1)])][field]=field==='fixed'?el.checked:el.value});$$('[data-draft-remove]').forEach(el=>el.onclick=()=>{draftTasks.splice(Number(el.dataset.draftRemove),1);renderDraftTasks()})}
$('#draft-task-add').onclick=()=>{if(draftTasks.length>=200)return;draftTasks.push({id:crypto.randomUUID(),text:'',status:'todo',due:'',owner:'',fixed:false});renderDraftTasks();$$('[data-draft-text]').at(-1)?.focus()};
async function changeTask(itemId,taskId,status){const i=items.find(i=>i.id===itemId);if(!i||!canEditItem(i))return;try{await persistItem({...i,tasks:i.tasks.map(t=>t.id===taskId?{...t,status}:t)})}catch{toast('Could not save that task. Refresh and try again.')}}
function bindBoardExtras(){
 $$('[data-comment]').forEach(b=>b.onclick=()=>openComments(b.dataset.comment));$$('[data-seat]').forEach(b=>b.onclick=()=>openSeating(items.find(i=>i.id===b.dataset.seat)));
 $$('[data-task-check]').forEach(b=>b.onchange=()=>changeTask(b.dataset.taskItem,b.dataset.taskCheck,b.checked?'done':'todo'));
 $$('[data-task-status]').forEach(b=>b.onchange=()=>changeTask(b.dataset.taskItem,b.dataset.taskStatus,b.value));
 $$('[data-task-view]').forEach(b=>b.onclick=async()=>{const i=items.find(i=>i.id===b.dataset.taskView);try{await persistItem({...i,task_view:i.task_view==='kanban'?'checklist':'kanban'})}catch{toast('Could not switch task view')}});
 $$('[data-task-drag]').forEach(b=>b.ondragstart=e=>{internalDrag=true;e.dataTransfer.setData('application/x-wedding-task',JSON.stringify({item:b.dataset.taskItem,task:b.dataset.taskDrag}));e.stopPropagation()});
 $$('[data-task-lane]').forEach(lane=>{lane.ondragover=e=>{if(internalDrag){e.preventDefault();e.stopPropagation()}};lane.ondrop=e=>{if(!internalDrag)return;e.preventDefault();e.stopPropagation();try{const value=JSON.parse(e.dataTransfer.getData('application/x-wedding-task'));if(value.item===lane.dataset.taskItem)void changeTask(value.item,value.task,lane.dataset.taskLane)}catch{}internalDrag=false}});
}
async function loadCloud(){if(!user||loading)return;demo=false;loading=true;render();try{
 const invite=new URLSearchParams(location.search).get('invite');if(invite){try{boardOwner=check(await db.rpc('ws_accept_invite',{invite_token:invite}));history.replaceState(null,'',location.pathname);toast('Invitation accepted. Welcome to the wedding board.')}catch(e){toast(e.message);history.replaceState(null,'',location.pathname)}}
 const memberships=check(await db.from('wedding_studio_members').select('*').eq('member_id',user.id));
 if(!boardOwner||boardOwner!==user.id&&!memberships.some(m=>m.board_owner===boardOwner))boardOwner=user.id;
 let own=check(await db.from('wedding_studio_boards').select('*').eq('user_id',user.id).maybeSingle());if(!own&&boardOwner===user.id){if(!await requestTrialStart()){loading=false;board={title:'Our wedding',wedding_date:''};items=[];workspaces=[];render();return}check(await db.from('wedding_studio_boards').insert({user_id:user.id,title:'Our wedding'}));own=check(await db.from('wedding_studio_boards').select('*').eq('user_id',user.id).single())}
 workspaces=check(await db.from('wedding_studio_boards').select('*').in('user_id',[user.id,...memberships.map(m=>m.board_owner)]));board=workspaces.find(b=>b.user_id===boardOwner)||own;
 const member=memberships.find(m=>m.board_owner===boardOwner);memberRole=boardOwner===user.id?'owner':member?.role||'view';memberTags=member?.tags||null;
 items=await fileURLs(check(await db.from('wedding_studio_items').select('*').eq('user_id',boardOwner).order('created_at'))||[]);loading=false;busy(false);render();void enrichExisting();if(pendingCapture){const capture=pendingCapture;pendingCapture=null;void importCapture(capture)}
 const purchase=new URLSearchParams(location.search).get('purchase');if(purchase){try{const data=await checkoutCall('verify',{purchase_ref:purchase});if(data.paid){history.replaceState(null,'',location.pathname);toast('Your wedding workspace is purchased.');await loadCloud()}}catch(e){toast(e.message)}}
 }catch(e){loading=false;$('#board').innerHTML='<div class="empty"><h2>Your board couldn’t load.</h2><p>Your saved ideas are still in your account. Check your connection, then try again.</p><button class="button" id="retry">Try again</button></div>';$('#retry').onclick=loadCloud;toast(e.message||'Unable to load your board')}}
function renderWorkspaceControls(){if(!user&&!demo){boardOwner=null;memberRole='owner';memberTags=null}$('#workspace-label').hidden=!user||workspaces.length<2;$('#workspace-select').innerHTML=workspaces.map(b=>`<option value="${esc(b.user_id)}" ${b.user_id===boardOwner?'selected':''}>${esc(b.title)}${b.user_id===user?.id?' · Yours':' · Shared'}</option>`).join('');$('#collaborate-open').hidden=!isOwner();$('#settings').disabled=!isOwner();$('#brief-open').hidden=!isOwner();$('#manage-briefs').hidden=!isOwner();for(const id of ['board-add','templates-open','tidy'])$('#'+id).disabled=(user||demo)&&!canEditBoard();$('#trial-open').hidden=!!user&&!!board.created_at&&!demo;$('#access-title').textContent=!user||demo?'14 DAYS FREE · NO CARD REQUIRED':!isOwner()?'SHARED WEDDING WORKSPACE':board.paid_at?'YOUR WORKSPACE · PURCHASED':editingActive()?'YOUR FREE TRIAL':'YOUR TRIAL HAS ENDED';const trialEnd=board.created_at?new Date(new Date(board.created_at).getTime()+14*86400000):null;$('#access-state').textContent=demo?'Temporary example · Try the features, then sign in for your own board.':!user?'14 days free · One wedding workspace · Your partner and unlimited vendors.':board.paid_until?'Purchased · Editing available through '+new Date(board.paid_until).toLocaleDateString():trialEnd?'Trial through '+trialEnd.toLocaleDateString()+(!offer.ready?' · Checkout is being connected; editing stays available during setup.':' · Keep your work with a one-time purchase.'):'Your free trial starts with your wedding workspace.';$('#purchase-open').textContent=board.paid_at?'Your workspace access':`Pricing · $${offer.price_cents/100} one-time`;}
