async function listPeople(){if(demo){$('#people-list').innerHTML='<p class="hint">Sign in to invite your partner and vendors to a saved board. This example lets you explore the permissions.</p>';return}const [members,invites]=await Promise.all([db.from('wedding_studio_members').select('*').eq('board_owner',boardOwner),db.from('wedding_studio_invites').select('*').eq('board_owner',boardOwner).is('accepted_at',null)]);const list=[...check(members).map(m=>({...m,type:'member',key:m.member_id})),...check(invites).map(m=>({...m,type:'invite',key:m.id}))];$('#people-list').innerHTML=list.map(m=>`<div class="shared-row"><b>${esc(m.email)}</b><p>${esc(m.role)} · ${m.tags?m.tags.map(esc).join(', '):'All tags'}${m.type==='invite'?' · Pending invitation':''}</p><button class="quiet" data-remove-person="${esc(m.key)}" data-person-type="${m.type}">Revoke access</button></div>`).join('');$$('[data-remove-person]').forEach(b=>b.onclick=async()=>{if(!await confirmAction('Revoke this access?','This person will lose access to your board. You can invite them again later.'))return;try{if(b.dataset.personType==='member')check(await db.from('wedding_studio_members').delete().eq('board_owner',boardOwner).eq('member_id',b.dataset.removePerson));else check(await db.from('wedding_studio_invites').delete().eq('id',b.dataset.removePerson));await listPeople();toast('Access revoked')}catch(e){$('#people-feedback').textContent=e.message}})}
