async function checkoutCall(action,body={}){const session=check(await db.auth.getSession()).session;if(!session)throw Error('Sign in to purchase your wedding workspace.');const r=await fetch(URL_BASE+'/functions/v1/wedding-studio-checkout?action='+action,{method:'POST',headers:{'Content-Type':'application/json',apikey:API_KEY,Authorization:'Bearer '+session.access_token},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'Checkout unavailable');return d}
