let pendingTrial=null;
function showPendingTrial(){if(!pendingTrial||$$('dialog[open]').length)return;$('#trial-price').textContent=`Then $${offer.price_cents/100} one-time${offer.introductory?' at launch · Regular price $49':''}. No subscription.`;$('#trial-modal').showModal()}
function requestTrialStart(){if(pendingTrial)return pendingTrial.promise;let resolve;const promise=new Promise(r=>resolve=r);pendingTrial={promise,resolve,userId:user.id};if($('#tour').open||$('#tour').hasAttribute('open'))$('#tour').close();showPendingTrial();return promise}
function finishTrialStart(accepted){const pending=pendingTrial;pendingTrial=null;$('#trial-modal').close();pending?.resolve(accepted&&user?.id===pending.userId)}
$('#trial-confirm').onclick=()=>finishTrialStart(true);
$('#trial-later').onclick=()=>finishTrialStart(false);
$('#trial-modal').addEventListener('cancel',e=>{e.preventDefault();finishTrialStart(false)});
$$('dialog').forEach(dialog=>dialog.addEventListener('close',()=>setTimeout(showPendingTrial,0)));
function startFreeTrial(){if(!user){showAuth();authMode='signup';setAuthMode();return}boardOwner=user.id;void loadCloud()}
$('#trial-open').onclick=startFreeTrial;
$('#pricing-trial').onclick=()=>{$('#purchase-modal').close();startFreeTrial()};
$('#checkout-start').onclick=async()=>{if(!user||!isOwner())return;$('#checkout-start').disabled=true;try{const d=await checkoutCall('checkout');location.assign(d.url)}catch(e){$('#purchase-feedback').textContent=e.message;$('#checkout-start').disabled=false}};
