let seatDraft=null,seatItem=null,seatRoom=null;
function mountSeatRoom(){const host=$('#seating-room'),guests=()=>seatDraft.guests,tableGuests=id=>guests().filter(g=>g.table===id),tableById=id=>seatDraft.tables.find(t=>t.id===id),unassignedGuests=()=>guests().filter(g=>!g.table),render=()=>{host.innerHTML=seatRoom.markup();seatRoom.bind()};seatRoom=SeatingRoom.create({app:host,tables:seatDraft.tables,guests,tableGuests,tableById,unassignedGuests,isAttending:()=>true,esc,storage:false,snapshot:()=>JSON.stringify({guests:seatDraft.guests,room:seatRoom?.snapshot()}),saveChange:()=>{$('#seating-feedback').textContent='Unsaved changes · Save seating plan to keep them on your board.'},toast,render});if(seatDraft.room)seatRoom.restore(seatDraft.room);render()}
function openSeating(item=null){if(!user&&!demo){showAuth();return}seatItem=item||items.find(i=>i.kind==='seating');seatDraft=structuredClone(seatItem?.seating||{guests:[],tables:Array.from({length:6},(_,n)=>({id:'table-'+(n+1),number:n+1,name:'Table '+(n+1),capacity:8,note:''}))});if(!seatDraft.guests)seatDraft.guests=[];$('#seating-guests').value=seatDraft.guests.map(g=>g.name).join('\n');$('#seating-tables').value=seatDraft.tables.length;$('#seating-feedback').textContent=seatItem?'Saved on your wedding board.':'Start with your guest list. This plan is included in your workspace.';$('#seating-setup').open=!seatDraft.guests.length;$('#seating-modal').showModal();mountSeatRoom();const editable=seatItem?canEditItem(seatItem):canEditBoard();$('#seating-save').disabled=!editable;$('#seating-apply').disabled=!editable;$('#seating-room').inert=!editable;$('#seating-guests').disabled=!editable;$('#seating-tables').disabled=!editable}
$('#seating-open').onclick=()=>openSeating();
$('#seating-apply').onclick=()=>{if(!canEditBoard())return;const names=$('#seating-guests').value.split('\n').map(s=>s.trim().slice(0,120)).filter(Boolean);if(names.length>500){$('#seating-feedback').textContent='Use up to 500 guests.';return}const count=Number($('#seating-tables').value);if(!Number.isInteger(count)||count<1||count>30){$('#seating-feedback').textContent='Choose between 1 and 30 tables.';return}seatDraft.room=seatRoom.snapshot();const used=new Set();seatDraft.guests=names.map(name=>{const old=seatDraft.guests.find(g=>g.name===name&&!used.has(g.id));if(old)used.add(old.id);return old||{id:crypto.randomUUID(),name,table:null,meal:'',dietary:'',accessibility:'',group:''}});seatDraft.tables=Array.from({length:count},(_,n)=>seatDraft.tables[n]||{id:'table-'+(n+1),number:n+1,name:'Table '+(n+1),capacity:8,note:''});seatDraft.guests.forEach(g=>{if(!seatDraft.tables.some(t=>t.id===g.table))g.table=null});mountSeatRoom();$('#seating-feedback').textContent='Guest list applied · Save seating plan to keep it.';};
$('#seating-save').onclick=async()=>{if(!guard())return;$('#seating-save').disabled=true;try{seatDraft.room=seatRoom.snapshot();const i={...seatItem,id:seatItem?.id||crypto.randomUUID(),kind:'seating',title:seatItem?.title||'Our seating plan',tags:seatItem?tagsFor(seatItem):[memberRole==='contribute'?memberTags?.[0]:'Reception'],category:'Reception',status:seatItem?.status||'Idea',notes:seatItem?.notes||'',colors:[],seating:seatDraft,x:seatItem?.x??25+items.length%3*300,y:seatItem?.y??25+Math.floor(items.length/3)*460};await persistItem(i);seatItem=i;$('#seating-feedback').textContent='Saved to your wedding board.';toast('Seating plan saved.')}catch(e){$('#seating-feedback').textContent=e.message}finally{$('#seating-save').disabled=false}};
$('#seating-print').onclick=()=>{const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print your seating plan.');return}w.opener=null;const markup=seatDraft.tables.map(t=>`<section><h2>${esc(t.name)}</h2><p>${seatDraft.guests.filter(g=>g.table===t.id).length} / ${t.capacity} seats</p><ol>${seatDraft.guests.filter(g=>g.table===t.id).map(g=>`<li>${esc(g.name)}</li>`).join('')}</ol></section>`).join('');w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(board.title)} · Seating plan</title><style>body{font-family:Arial,sans-serif;max-width:900px;margin:40px auto;padding:20px;color:#172c3a}section{break-inside:avoid;border:1px solid #ddd;padding:20px;margin:20px 0}li{margin:8px 0}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print / Save PDF</button><h1>${esc(board.title)} · Seating plan</h1><p>${esc(board.wedding_date)} · ${seatDraft.guests.length} guests</p>${markup}<section><h2>Still to place</h2><p>${seatDraft.guests.filter(g=>!g.table).map(g=>esc(g.name)).join(', ')||'Everyone is placed.'}</p></section><footer>Prepared with The Wedding Studio by TSS</footer></body></html>`);w.document.close()};
// Store view preference only; wedding content remains in the account.
try{const preferred=localStorage.getItem('wedding-studio-view');if(['cards','canvas'].includes(preferred))view=preferred}catch{}
for(const [id,value] of [['cards-view','cards'],['canvas-view','canvas']])$('#'+id).onclick=()=>{view=value;try{localStorage.setItem('wedding-studio-view',view)}catch{}render()};
init();void loadOffer();
